# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: Sequence[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for pupil in students:
        if not pupil.email:
            name = pupil.display_name
            raise ProjectError(f"no email for {name}")


def _cells(pupil: Student) -> List[str]:
    return [pupil.display_name, pupil.section, pupil.email]


def _widths(table: List[List[str]]) -> List[int]:
    return [max(map(len, column)) for column in zip(*table)]


def _line(row: List[str], widths: List[int]) -> str:
    pairs = zip(row, widths)
    cells = [text.ljust(size) for text, size in pairs]
    return "  ".join(cells).rstrip()


def _by_name(pupil: Student) -> str:
    return pupil.display_name.lower()


# ---
def contact_rows(students: Sequence[Student]) -> List[str]:
    """Rows of name, section and email, by name."""
    _check(students)
    ordered = sorted(students, key=_by_name)
    table = [_cells(pupil) for pupil in ordered]
    widths = _widths(table)
    return [_line(row, widths) for row in table]
